var n=[{title:`Statisk stretching`,text:`En statisk stretch håller försiktigt en muskel eller led nära slutet av dess bekväma omfång. En vadstretch mot en vägg eller en stödd höftböjarstretch kan till exempel hållas en kort stund utan att studsa. Den ska kännas som mild spänning, aldrig som skarp smärta eller domningar.`},{title:`Dynamisk stretching`,text:`Dynamisk stretching rör sig genom ett användbart omfång gång på gång: bensvingar som du kan kontrollera, armcirklar, växlande utfall. Varje repetition är medveten, inte studsande eller hastig. De här övningarna passar naturligt in i en uppvärmning för löpning, lyft och idrott.`},{title:`När du använder var och en`,text:`Före explosiv ansträngning fungerar gradvis dynamisk rörelse och övning av själva övningen oftast bäst. Lång, intensiv statisk stretching strax innan kan tillfälligt minska kraft eller effekt, medan några korta hållningar är mindre av ett problem. Efter träning eller i ett separat pass är statisk stretching ett rimligt sätt att arbeta med flexibilitet.`},{title:`Hur mycket du ska göra`,text:`Använd korta, bekväma hållningar och upprepa dem över veckor i stället för att tvinga fram ett nytt omfång under ett pass. För dynamiska övningar, börja med ett litet omfång och vidga det bara medan rörelsen förblir kontrollerad. Stretching behöver inte göra ont för att fungera, och mer flexibilitet hjälper inte vid varje uppgift.`},{title:`Vad stretching inte kan lova`,text:`Använd dynamiska övningar för att göra dig redo för aktiv rörelse och statiska hållningar när flexibilitet är målet. Ingen av dem gör dig skadesäker eller förebygger träningsvärk på ett pålitligt sätt. Om smärtan kvarstår, be en läkare eller fysioterapeut om råd som passar dig.`}];var r=[{label:`ACE 2026: praktisk vägledning om stretching`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`ACE 2026: rörlighet jämfört med flexibilitet`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`NHS: skonsamma nedvarvningsövningar`,url:`https://www.nhs.uk/live-well/exercise/strength-and-resistance/body-blast-cool-down/`}];var a={sections:n,sources:r};export{a as default,n as sections,r as sources};